class SmartDevice {
    #name;
    #isOn;

    constructor(name) {
        this.#name = name;
        this.#isOn = false;
    }

    turnOn() {
        this.#isOn = true;
        return `${this.#name} is ON.`;
    }

    turnOff() {
        this.#isOn = false;
        return `${this.#name} is OFF.`;
    }

    getIsOn() {
        return this.#isOn;
    }

    getStatus() {
        return `${this.#name} is currently ${this.#isOn ? 'ON' : 'OFF'}.`;
    }
}

class SmartLight extends SmartDevice {
    #brightness;

    constructor(name) {
        super(name);
        this.#brightness = 50;
    }

    setBrightness(level) {
        if (level < 0 || level > 100) {
            return "Error: Brightness level must be between 0 and 100.";
        }
        this.#brightness = level;
        return `Brightness set to ${this.#brightness}%.`;
    }

    getStatus() {
        const baseStatus = super.getStatus();
        if (this.getIsOn()) {
            return `${baseStatus} Brightness: ${this.#brightness}%.`;
        }
        return baseStatus;
    }
}

class SmartThermostat extends SmartDevice {
    #temperature;

    constructor(name) {
        super(name);
        this.#temperature = 20;
    }

    setTemperature(temp) {
        if (temp < 10 || temp > 30) {
            return "Error: Temperature must be between 10°C and 30°C.";
        }
        this.#temperature = temp;
        return `Temperature set to ${this.#temperature}°C.`;
    }

    getStatus() {
        const baseStatus = super.getStatus();
        if (this.getIsOn()) {
            return `${baseStatus} Temperature: ${this.#temperature}°C.`;
        }
        return baseStatus;
    }
}

